// EDUVERSE chunk: dikdin — generated by build-split.js from canonical bank files. Do not hand-edit.
window.EDUVERSE_BANK_DIKDIN = [{"id":"DKTWK01","subtes":"Tes Wawasan Kebangsaan","aspek":"Nasionalisme","soal":"Dalam kehidupan berbangsa dan bernegara, sikap nasionalisme paling tepat diwujudkan dalam bentuk ...","opsi":["Menganggap budaya bangsa lain selalu lebih rendah dan tidak layak dipelajari.","Mendahulukan kepentingan kelompok sendiri di atas kepentingan bangsa.","Mendahulukan kepentingan bangsa dan negara di atas kepentingan pribadi atau golongan, sambil tetap menghormati bangsa lain.","Menutup diri dari pergaulan dengan warga negara lain dalam segala hal.","Menilai kemajuan bangsa hanya dari banyaknya kekayaan alam yang dimiliki."],"kunci":2,"bahas":"Nasionalisme berarti cinta tanah air yang diwujudkan dengan menempatkan kepentingan bangsa dan negara lebih utama daripada kepentingan pribadi atau golongan. Sikap tersebut tidak menolak pergaulan dengan bangsa lain dan tidak merendahkan bangsa lain. Menganggap budaya lain selalu lebih rendah, mendahulukan kelompok sendiri, menutup diri dari pergaulan, atau mengukur kemajuan hanya dari kekayaan alam tidak menggambarkan wujud nasionalisme tersebut."},{"id":"DKTWK02","subtes":"Tes Wawasan Kebangsaan","aspek":"Nasionalisme","soal":"Di sebuah lingkungan tempat tinggal yang warganya berasal dari berbagai daerah, sikap yang paling mencerminkan nasionalisme adalah ...","opsi":["Menghormati adat dan kebiasaan tetangga yang berbeda, serta ikut serta dalam kerja bakti bersama warga.","Hanya bergaul dengan tetangga yang berasal dari daerah yang sama.","Meminta seluruh warga mengikuti adat salah satu daerah saja.","Tidak peduli terhadap kegiatan bersama selama rumah sendiri sudah bersih.","Menertawakan kebiasaan tetangga yang berbeda dengan kebiasaan sendiri."],"kunci":0,"bahas":"Menghormati perbedaan adat antartetangga dan ikut dalam kerja bakti bersama menunjukkan persatuan dalam keberagaman serta kepedulian terhadap kepentingan bersama. Bergaul hanya dengan warga sedaerah, memaksakan satu adat, tidak peduli pada kegiatan bersama, atau menertawakan kebiasaan orang lain melemahkan persatuan di lingkungan tersebut."},{"id":"DKTWK03","subtes":"Tes Wawasan Kebangsaan","aspek":"Integritas","soal":"Seorang petugas pelayanan ditawari uang oleh warga agar berkasnya didahulukan dari antrean. Tindakan yang paling mencerminkan integritas adalah ...","opsi":["Menerima uang tersebut karena warga memberikannya dengan sukarela.","Menerima uang tersebut, tetapi tetap melayani sesuai antrean.","Mendahulukan berkas warga tersebut tanpa menerima uang.","Meminta warga menambah uang agar berkasnya benar-benar didahulukan.","Menolak uang tersebut dengan sopan dan melayani warga sesuai antrean dan ketentuan yang berlaku."],"kunci":4,"bahas":"Menolak pemberian yang dimaksudkan untuk mendahulukan layanan dan tetap melayani sesuai antrean dan ketentuan menunjukkan kejujuran dan keteguhan pada aturan. Menerima pemberian, mendahulukan berkas di luar antrean, atau meminta tambahan pemberian menyalahi prinsip pelayanan yang adil dan dapat merugikan warga lain."},{"id":"DKTWK04","subtes":"Tes Wawasan Kebangsaan","aspek":"Integritas","soal":"Andini menemukan dompet berisi uang dan kartu identitas di jalan dekat sekolahnya. Tindakan yang paling mencerminkan integritas adalah ...","opsi":["Mengambil uangnya dan membuang dompet beserta isinya.","Mengembalikan dompet beserta seluruh isinya kepada pemiliknya atau menyerahkannya kepada pihak yang berwenang.","Menyimpan dompet itu sambil menunggu pemiliknya datang mencarinya tanpa memberi tahu siapa pun.","Mengambil sebagian uangnya sebagai imbalan karena sudah menemukan dompet itu.","Mengembalikan dompetnya, tetapi menyimpan kartu identitasnya sebagai kenang-kenangan."],"kunci":1,"bahas":"Mengembalikan dompet beserta seluruh isinya kepada pemilik atau menyerahkannya kepada pihak yang berwenang menunjukkan kejujuran dan tanggung jawab. Mengambil uang, menyimpan dompet tanpa memberi tahu siapa pun, atau menyimpan kartu identitas pemilik membuat pemilik kehilangan haknya dan tidak menunjukkan sikap yang jujur."},{"id":"DKTWK05","subtes":"Tes Wawasan Kebangsaan","aspek":"Bela negara","soal":"Bagi seorang pelajar, wujud bela negara dalam kehidupan sehari-hari yang paling tepat adalah ...","opsi":["Membawa senjata ke sekolah untuk berjaga-jaga.","Menghindari semua kegiatan sekolah yang melibatkan banyak orang.","Menyebarkan kabar yang belum jelas kebenarannya agar cepat dikenal.","Belajar dengan sungguh-sungguh, menaati tata tertib, dan menjaga nama baik sekolah serta bangsa.","Hanya memikirkan nilai sendiri dan tidak peduli pada teman yang kesulitan."],"kunci":3,"bahas":"Bela negara bagi pelajar diwujudkan tanpa kekerasan, antara lain dengan belajar sungguh-sungguh, menaati tata tertib, dan menjaga nama baik sekolah serta bangsa. Membawa senjata, menghindari kegiatan bersama, menyebarkan kabar yang belum jelas, atau tidak peduli pada teman bukan wujud bela negara dan dapat membahayakan diri sendiri maupun orang lain."},{"id":"DKTWK06","subtes":"Tes Wawasan Kebangsaan","aspek":"Bela negara","soal":"UUD Negara Republik Indonesia Tahun 1945 menyatakan bahwa setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara. Ketentuan tersebut tercantum dalam ...","opsi":["Pasal 28A UUD Negara Republik Indonesia Tahun 1945","Pasal 29 ayat (2) UUD Negara Republik Indonesia Tahun 1945","Pasal 27 ayat (3) UUD Negara Republik Indonesia Tahun 1945","Pasal 31 ayat (1) UUD Negara Republik Indonesia Tahun 1945","Pasal 34 ayat (1) UUD Negara Republik Indonesia Tahun 1945"],"kunci":2,"bahas":"Bunyi ketentuan tentang hak dan kewajiban setiap warga negara untuk ikut serta dalam upaya pembelaan negara tercantum dalam Pasal 27 ayat (3) UUD Negara Republik Indonesia Tahun 1945. Ketentuan lain yang disebut dalam soal mengatur hal yang berbeda, yaitu hak mempertahankan hidup, jaminan kemerdekaan beragama, hak memperoleh pendidikan, dan tanggung jawab negara terhadap warga yang kurang mampu."},{"id":"DKTWK07","subtes":"Tes Wawasan Kebangsaan","aspek":"Pilar negara","soal":"Dalam rapat warga, perbedaan pendapat diselesaikan dengan musyawarah sampai tercapai kesepakatan bersama, dan hasil kesepakatan dihormati oleh semua pihak. Sikap tersebut mencerminkan sila Pancasila yang berbunyi ...","opsi":["Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan","Ketuhanan Yang Maha Esa","Kemanusiaan yang adil dan beradab","Persatuan Indonesia","Keadilan sosial bagi seluruh rakyat Indonesia"],"kunci":0,"bahas":"Musyawarah untuk mencapai mufakat dan menghormati hasil kesepakatan bersama merupakan perwujudan sila Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan. Sila lain mengatur ketuhanan, kemanusiaan, persatuan, dan keadilan sosial, yang tidak menjadi gagasan utama dalam peristiwa rapat warga tersebut."},{"id":"DKTWK08","subtes":"Tes Wawasan Kebangsaan","aspek":"Pilar negara","soal":"Semboyan Bhinneka Tunggal Ika bermakna bahwa ...","opsi":["Seluruh warga harus memiliki adat dan bahasa daerah yang sama.","Setiap daerah harus berdiri sendiri tanpa hubungan dengan daerah lain.","Perbedaan antarwarga harus dihilangkan agar tidak menimbulkan masalah.","Kelompok yang paling besar jumlahnya berhak mengatur kelompok lain.","Keberagaman suku, agama, dan budaya tetap menyatu dalam satu kesatuan bangsa dan negara."],"kunci":4,"bahas":"Bhinneka Tunggal Ika berarti berbeda-beda tetapi tetap satu jua. Makna tersebut menempatkan keberagaman suku, agama, dan budaya sebagai kekayaan yang tetap menyatu dalam satu kesatuan bangsa dan negara, bukan sebagai alasan untuk menyeragamkan seluruh warga, memisahkan daerah, menghilangkan perbedaan, atau memberi hak kepada kelompok yang lebih besar untuk mengatur kelompok lain."},{"id":"DKTWK09","subtes":"Tes Wawasan Kebangsaan","aspek":"Bahasa negara","soal":"Kedudukan bahasa Indonesia sebagai bahasa persatuan paling tepat ditunjukkan oleh peran bahasa Indonesia sebagai ...","opsi":["Pengganti seluruh bahasa daerah dalam percakapan sehari-hari di rumah.","Alat komunikasi bersama yang mempersatukan warga dari berbagai suku dan daerah.","Bahasa yang hanya boleh digunakan dalam acara kenegaraan.","Bahasa yang melarang penggunaan bahasa daerah dalam segala keadaan.","Bahasa yang hanya digunakan oleh warga yang tinggal di ibu kota."],"kunci":1,"bahas":"Sebagai bahasa persatuan, bahasa Indonesia berfungsi sebagai alat komunikasi bersama yang mempersatukan warga dari berbagai suku dan daerah. Peran tersebut tidak menghapus bahasa daerah, tidak terbatas pada acara kenegaraan, tidak melarang bahasa daerah dalam segala keadaan, dan tidak terbatas pada warga ibu kota."},{"id":"DKTWK10","subtes":"Tes Wawasan Kebangsaan","aspek":"Bahasa negara","soal":"Dalam surat undangan kegiatan sekolah, kalimat yang menggunakan bahasa Indonesia dengan baik dan benar adalah ...","opsi":["Buat temen-temen semua, jangan lupa dateng ya besok pagi.","Acara ini bakalan seru banget, so jangan sampai ketinggalan.","Diharapkan kehadiran Bapak/Ibu, karena acara ini penting banget buat sekolah kita.","Kami mengundang Bapak dan Ibu untuk menghadiri kegiatan peringatan Hari Pendidikan Nasional di sekolah.","Nanti acaranya diadain di aula, jangan telat-telat ya guys."],"kunci":3,"bahas":"Kalimat undangan yang baik dan benar memakai ragam formal yang runtut dan mudah dipahami, tanpa kata gaul dan tanpa campuran bahasa lain. Kalimat lain memakai kata gaul, campuran bahasa, atau susunan yang tidak runtut, sehingga kurang sesuai untuk surat undangan kegiatan sekolah."},{"id":"DKTIU01","subtes":"Tes Intelegensia Umum","aspek":"Verbal — Analogi","soal":"Koki : Hidangan = Penjahit : ... Kata yang tepat untuk melengkapi analogi tersebut adalah ...","opsi":["Jarum","Pakaian","Pelanggan","Toko kain","Gunting"],"kunci":1,"bahas":"Koki menghasilkan hidangan sebagai hasil karyanya, dan penjahit menghasilkan pakaian sebagai hasil karyanya. Jarum dan gunting merupakan alat kerja penjahit, pelanggan merupakan pihak yang dilayani, dan toko kain merupakan tempat memperoleh bahan, sehingga semuanya tidak menunjukkan hubungan pembuat dengan hasil karya."},{"id":"DKTIU02","subtes":"Tes Intelegensia Umum","aspek":"Verbal — Analogi","soal":"Roda : Sepeda = Layar : ... Kata yang tepat untuk melengkapi analogi tersebut adalah ...","opsi":["Laut","Nahkoda","Angin","Kapal","Pelabuhan"],"kunci":3,"bahas":"Roda merupakan bagian dari sepeda, dan layar merupakan bagian dari kapal. Laut dan pelabuhan merupakan tempat kapal berada, nahkoda merupakan orang yang menjalankan kapal, dan angin merupakan tenaga yang menggerakkan layar, sehingga semuanya tidak menunjukkan hubungan bagian dengan keseluruhan."},{"id":"DKTIU03","subtes":"Tes Intelegensia Umum","aspek":"Verbal — Silogisme","soal":"Perhatikan dua pernyataan berikut. Pernyataan 1: Semua pegawai bagian arsip wajib mengikuti pelatihan kearsipan. Pernyataan 2: Semua peserta pelatihan kearsipan menerima sertifikat pelatihan. Kesimpulan yang tepat berdasarkan kedua pernyataan tersebut adalah ...","opsi":["Semua pegawai bagian arsip menerima sertifikat pelatihan.","Semua penerima sertifikat pelatihan adalah pegawai bagian arsip.","Sebagian pegawai bagian arsip tidak menerima sertifikat pelatihan.","Semua peserta pelatihan kearsipan adalah pegawai bagian arsip.","Tidak ada pegawai bagian arsip yang menerima sertifikat pelatihan."],"kunci":0,"bahas":"Semua pegawai bagian arsip termasuk peserta pelatihan kearsipan, dan semua peserta pelatihan menerima sertifikat, sehingga semua pegawai bagian arsip menerima sertifikat. Pernyataan lain membalik hubungan antarkelompok, membatasi kesimpulan menjadi sebagian, atau meniadakan kesimpulan yang mengikuti kedua pernyataan tersebut."},{"id":"DKTIU04","subtes":"Tes Intelegensia Umum","aspek":"Verbal — Silogisme","soal":"Perhatikan dua pernyataan berikut. Pernyataan 1: Semua kendaraan dinas harus menjalani uji kelayakan. Pernyataan 2: Mobil X bukan kendaraan dinas. Kesimpulan yang tepat berdasarkan kedua pernyataan tersebut adalah ...","opsi":["Mobil X harus menjalani uji kelayakan.","Mobil X tidak harus menjalani uji kelayakan.","Mobil X adalah kendaraan dinas yang belum diuji.","Semua mobil yang bukan kendaraan dinas tidak perlu diuji.","Tidak ada kesimpulan yang pasti tentang kewajiban uji kelayakan bagi mobil X dari kedua pernyataan tersebut."],"kunci":4,"bahas":"Pernyataan yang tersedia hanya mengatur kendaraan dinas, sedangkan mobil X dinyatakan bukan kendaraan dinas. Dari informasi tersebut saja tidak dapat dipastikan apakah mobil X harus menjalani uji kelayakan atau tidak, karena kewajiban bagi mobil yang bukan kendaraan dinas tidak dinyatakan. Menyimpulkan kewajiban atau ketiadaan kewajiban bagi mobil X melampaui informasi yang tersedia."},{"id":"DKTIU05","subtes":"Tes Intelegensia Umum","aspek":"Verbal — Analitis","soal":"Empat orang, yaitu Rina, Sari, Tono, dan Udin, duduk berjajar pada kursi nomor 1 sampai nomor 4 dari kiri ke kanan. Diketahui: Rina duduk di kursi ujung; Tono duduk bersebelahan dengan Sari; Udin tidak duduk bersebelahan dengan Rina. Pernyataan yang pasti benar adalah ...","opsi":["Tono duduk di kursi nomor 2.","Sari duduk bersebelahan dengan Rina.","Udin duduk di kursi ujung.","Tono duduk bersebelahan dengan Udin.","Rina duduk di kursi nomor 1."],"kunci":2,"bahas":"Rina menempati kursi ujung. Udin tidak bersebelahan dengan Rina. Bila Udin menempati kursi tengah, kursi yang tersisa bagi Sari dan Tono tidak bersebelahan, sehingga syarat Tono bersebelahan dengan Sari tidak terpenuhi. Karena itu Udin menempati kursi ujung yang berlawanan dengan kursi Rina, sedangkan Sari dan Tono menempati dua kursi tengah dalam urutan yang dapat bertukar. Kedudukan Udin di kursi ujung berlaku pada semua susunan yang memenuhi syarat, sedangkan kedudukan Tono, Sari, dan Rina dapat berubah antar susunan."},{"id":"DKTIU06","subtes":"Tes Intelegensia Umum","aspek":"Verbal — Analitis","soal":"Empat siswa, yaitu Andi, Budi, Candra, dan Dewi, mempresentasikan tugas pada hari Senin, Selasa, Rabu, dan Kamis, masing-masing satu orang setiap hari. Diketahui: Andi tampil sebelum Budi; Candra tampil pada hari Rabu; Dewi tidak tampil pada hari Senin. Pernyataan yang pasti benar adalah ...","opsi":["Budi tampil pada hari Kamis.","Andi tampil pada hari Senin.","Dewi tampil pada hari Selasa.","Budi tampil tepat setelah Andi.","Dewi tampil setelah Candra."],"kunci":1,"bahas":"Candra menempati hari Rabu, sehingga hari Senin, Selasa, dan Kamis tersisa bagi Andi, Budi, dan Dewi. Dewi tidak tampil pada hari Senin, dan Andi harus tampil sebelum Budi, sehingga Andi hanya dapat menempati hari Senin. Susunan yang memenuhi syarat hanya menyisakan dua kemungkinan bagi Budi dan Dewi pada hari Selasa dan Kamis, sehingga pernyataan tentang hari tampil Budi dan Dewi dapat berubah, sedangkan hari tampil Andi tetap."},{"id":"DKTIU07","subtes":"Tes Intelegensia Umum","aspek":"Numerik — Berhitung","soal":"Hitunglah hasil dari (48 × 12) − (360 ÷ 4).","opsi":["476","492","480","486","496"],"kunci":3,"bahas":"Hasil 48 dikali 12 adalah 576, dan hasil 360 dibagi 4 adalah 90. Selisih 576 dan 90 adalah 486."},{"id":"DKTIU08","subtes":"Tes Intelegensia Umum","aspek":"Numerik — Berhitung","soal":"Harga sebuah tas adalah Rp180.000. Tas tersebut dijual dengan potongan harga 25%. Seorang pembeli membayar dengan uang Rp150.000. Berapa uang kembalian yang diterima pembeli tersebut?","opsi":["Rp15.000","Rp20.000","Rp30.000","Rp45.000","Rp10.000"],"kunci":0,"bahas":"Potongan harga 25% dari Rp180.000 adalah Rp45.000, sehingga harga yang harus dibayar adalah Rp135.000. Pembeli membayar Rp150.000, sehingga uang kembaliannya adalah Rp150.000 dikurangi Rp135.000, yaitu Rp15.000."},{"id":"DKTIU09","subtes":"Tes Intelegensia Umum","aspek":"Numerik — Deret angka","soal":"Perhatikan barisan bilangan berikut: 2, 3, 6, 11, 18, ... Bilangan berikutnya dalam barisan tersebut adalah ...","opsi":["25","26","28","29","27"],"kunci":4,"bahas":"Jarak antara dua bilangan yang berurutan adalah 1, 3, 5, dan 7. Jarak tersebut bertambah 2 pada setiap langkah, sehingga jarak berikutnya adalah 9. Bilangan berikutnya adalah 18 ditambah 9, yaitu 27."},{"id":"DKTIU10","subtes":"Tes Intelegensia Umum","aspek":"Numerik — Perbandingan kuantitatif","soal":"Kuantitas P adalah 5/8 dari 320. Kuantitas Q adalah 75% dari 240. Hubungan yang benar antara kuantitas P dan kuantitas Q adalah ...","opsi":["P lebih kecil daripada Q.","P sama dengan Q.","P lebih besar daripada Q.","Hubungan antara P dan Q tidak dapat ditentukan.","P dua kali Q."],"kunci":2,"bahas":"Kuantitas P adalah 5/8 dikali 320, yaitu 200, karena 320 dibagi 8 adalah 40 dan 40 dikali 5 adalah 200. Kuantitas Q adalah 75% dikali 240, yaitu 180, karena 75% sama dengan 3/4 dan 3/4 dikali 240 adalah 180. Karena 200 lebih besar daripada 180, kuantitas P lebih besar daripada kuantitas Q."},{"id":"DKTIU11","subtes":"Tes Intelegensia Umum","aspek":"Numerik — Soal cerita","soal":"Sebuah pekerjaan dapat diselesaikan oleh 6 pekerja dalam 12 hari. Jika jumlah pekerja ditambah menjadi 9 orang dan setiap pekerja memiliki kemampuan yang sama, pekerjaan tersebut dapat diselesaikan dalam ...","opsi":["6 hari","8 hari","9 hari","10 hari","18 hari"],"kunci":1,"bahas":"Jumlah pekerjaan setara dengan 6 pekerja dikali 12 hari, yaitu 72 pekerja-hari. Dengan 9 pekerja, waktu yang dibutuhkan adalah 72 dibagi 9, yaitu 8 hari."},{"id":"DKTKP01","subtes":"Tes Karakteristik Pribadi","aspek":"Pelayanan publik","soal":"Seorang warga datang ke loket pelayanan menjelang jam tutup dengan membawa berkas yang belum lengkap. Sebagai petugas loket, tindakan yang paling tepat adalah ...","opsi":["Menjelaskan dengan sopan dokumen yang masih kurang, memeriksa berkas yang sudah dibawa, dan memberi tahu langkah berikutnya agar warga tidak perlu bolak-balik.","Menyuruh warga pulang dan datang lagi besok tanpa menjelaskan dokumen yang kurang.","Menerima berkas yang belum lengkap tanpa memberi tahu warga agar warga cepat pulang.","Melayani warga tersebut dengan mendahulukan dari warga lain yang sudah antre lebih dahulu.","Meminta warga menunggu di luar loket sampai seluruh antrean selesai tanpa memberi penjelasan."],"kunci":0,"bahas":"Menjelaskan dokumen yang kurang dengan sopan, memeriksa berkas yang sudah dibawa, dan memberi tahu langkah berikutnya membantu warga menyelesaikan urusannya tanpa bolak-balik dan tetap menjaga ketertiban antrean. Menyuruh pulang tanpa penjelasan, menerima berkas yang belum lengkap tanpa pemberitahuan, mendahulukan dari antrean, atau membiarkan warga menunggu tanpa penjelasan kurang tepat karena tidak membantu warga memahami urusannya atau tidak adil bagi warga lain. Tindakan-tindakan tersebut bukan tanpa maksud baik, tetapi kurang memenuhi kepentingan warga dan ketertiban pelayanan."},{"id":"DKTKP02","subtes":"Tes Karakteristik Pribadi","aspek":"Pelayanan publik","soal":"Seorang warga lanjut usia tampak kebingungan di ruang tunggu karena tidak memahami cara mengambil nomor antrean. Tindakan yang paling tepat adalah ...","opsi":["Membiarkannya karena mengambil nomor antrean adalah urusan warga sendiri.","Memintanya bertanya kepada warga lain yang sedang menunggu.","Mendekatinya dengan ramah, membantunya mengambil nomor antrean, dan menjelaskan alur pelayanan dengan sabar.","Memintanya pulang dan datang kembali bersama anggota keluarga.","Mengambilkan nomor antrean tanpa menjelaskan alur pelayanan kepadanya."],"kunci":2,"bahas":"Mendekati warga lanjut usia dengan ramah, membantu mengambil nomor antrean, dan menjelaskan alur pelayanan dengan sabar memenuhi kebutuhan warga yang membutuhkan bantuan dan membuatnya dapat mengikuti pelayanan dengan tenang. Membiarkannya, menyerahkan bantuan kepada warga lain, memintanya pulang, atau mengambilkan nomor tanpa penjelasan kurang tepat karena warga tetap kebingungan atau kehilangan kesempatan dilayani. Langkah-langkah tersebut bukan sepenuhnya keliru, tetapi kurang menunjukkan kepedulian pelayanan."},{"id":"DKTKP03","subtes":"Tes Karakteristik Pribadi","aspek":"Pelayanan publik","soal":"Seorang warga mengeluh karena pelayanannya berjalan lebih lambat dari waktu yang diperkirakan. Tindakan yang paling tepat adalah ...","opsi":["Mengabaikan keluhan tersebut dan melanjutkan pekerjaan seperti biasa.","Menyalahkan warga karena datang pada jam yang ramai.","Menjanjikan pelayanan selesai dalam lima menit meskipun hal itu belum pasti.","Meminta warga mengeluh secara tertulis dan menolak berbicara dengannya.","Mendengarkan keluhan dengan tenang, menyampaikan permohonan maaf atas ketidaknyamanan, menjelaskan penyebab keterlambatan dengan jujur, dan memberi tahu perkiraan waktu penyelesaian."],"kunci":4,"bahas":"Mendengarkan keluhan dengan tenang, menyampaikan permohonan maaf, menjelaskan penyebab keterlambatan dengan jujur, dan memberi tahu perkiraan waktu penyelesaian menunjukkan penghormatan kepada warga dan memberinya kepastian. Mengabaikan keluhan, menyalahkan warga, menjanjikan waktu yang belum pasti, atau menolak berbicara kurang tepat karena tidak menyelesaikan keluhan atau menimbulkan harapan yang tidak dapat dipenuhi. Langkah-langkah tersebut bukan tanpa alasan, tetapi kurang menjaga kepercayaan warga."},{"id":"DKTKP04","subtes":"Tes Karakteristik Pribadi","aspek":"Jejaring kerja","soal":"Anda membutuhkan data dari unit lain untuk menyelesaikan laporan, tetapi rekan di unit tersebut sedang sibuk. Tindakan yang paling tepat adalah ...","opsi":["Mengambil data dari arsip unit lain tanpa memberi tahu rekan di unit tersebut.","Menghubungi rekan tersebut dengan sopan, menjelaskan data yang dibutuhkan, dan menyepakati waktu penyerahan yang realistis.","Menunda laporan tanpa memberi tahu siapa pun sampai data tersedia sendiri.","Meminta atasan menegur rekan tersebut agar segera menyerahkan data.","Menyusun laporan dengan data perkiraan tanpa memeriksa data yang sebenarnya."],"kunci":1,"bahas":"Menghubungi rekan dengan sopan, menjelaskan data yang dibutuhkan, dan menyepakati waktu penyerahan yang realistis menjaga hubungan kerja yang baik dan memberi kepastian bagi penyelesaian laporan. Mengambil data tanpa pemberitahuan, menunda laporan tanpa pemberitahuan, langsung meminta teguran atasan, atau memakai data perkiraan kurang tepat karena dapat merusak kepercayaan, menghambat laporan, atau menghasilkan laporan yang tidak akurat. Langkah-langkah tersebut bukan sepenuhnya tanpa pertimbangan, tetapi kurang mengutamakan kerja sama yang saling menghormati."},{"id":"DKTKP05","subtes":"Tes Karakteristik Pribadi","aspek":"Jejaring kerja","soal":"Dalam sebuah tim, pembagian tugas dirasa tidak merata dan menimbulkan ketidaknyamanan antaranggota. Tindakan yang paling tepat adalah ...","opsi":["Membiarkan ketidaknyamanan itu karena pembagian tugas sudah ditetapkan.","Mengerjakan seluruh tugas sendiri agar tidak ada lagi perdebatan.","Menyalahkan anggota yang dianggap mendapat tugas paling ringan di depan tim.","Mengajak tim berdiskusi secara terbuka dan mengusulkan pembagian tugas yang lebih adil berdasarkan beban dan kemampuan masing-masing anggota.","Meminta pindah ke tim lain agar tidak terlibat dalam masalah tersebut."],"kunci":3,"bahas":"Berdiskusi secara terbuka dan mengusulkan pembagian tugas yang lebih adil berdasarkan beban dan kemampuan memberi ruang bagi setiap anggota untuk menyampaikan pandangan dan mencari kesepakatan bersama. Membiarkan ketidaknyamanan, mengerjakan seluruh tugas sendiri, menyalahkan anggota lain, atau pindah tim kurang tepat karena masalah pembagian tugas tidak terselesaikan atau hubungan antaranggota memburuk. Langkah-langkah tersebut bukan tanpa maksud meredakan keadaan, tetapi kurang menyelesaikan akar masalah secara bersama."},{"id":"DKTKP06","subtes":"Tes Karakteristik Pribadi","aspek":"Jejaring kerja","soal":"Seorang rekan baru dari daerah lain bergabung dengan tim Anda dan belum mengenal cara kerja tim. Tindakan yang paling tepat adalah ...","opsi":["Menyambutnya dengan ramah, memperkenalkannya kepada anggota tim, dan menawarkan bantuan agar ia dapat beradaptasi dengan cara kerja tim.","Membiarkannya belajar sendiri karena setiap orang harus mandiri.","Hanya menyapanya bila ia bertanya terlebih dahulu.","Memberinya tugas paling sulit sejak hari pertama agar ia cepat belajar.","Membatasi pergaulan dengannya sampai ia memahami cara kerja tim."],"kunci":0,"bahas":"Menyambut rekan baru dengan ramah, memperkenalkannya kepada tim, dan menawarkan bantuan membantunya beradaptasi dan membangun kerja sama sejak awal. Membiarkannya belajar sendiri, menunggu ia bertanya, langsung memberinya tugas paling sulit, atau membatasi pergaulan dengannya kurang tepat karena memperlambat adaptasi dan melemahkan kebersamaan tim. Langkah-langkah tersebut bukan sepenuhnya tanpa dasar, tetapi kurang menunjukkan dukungan kepada rekan baru."},{"id":"DKTKP07","subtes":"Tes Karakteristik Pribadi","aspek":"Sosial budaya","soal":"Kegiatan bersama tim dijadwalkan pada hari yang merupakan hari besar bagi salah satu anggota tim yang berbeda keyakinan. Tindakan yang paling tepat adalah ...","opsi":["Tetap melaksanakan kegiatan tanpa memberi tahu anggota tersebut.","Membatalkan kegiatan tanpa berdiskusi dengan seluruh anggota tim.","Menghormati hari besar anggota tersebut, menanyakan kesediaannya, dan mengajak tim mencari jadwal yang dapat diikuti bersama.","Meminta anggota tersebut mengabaikan hari besarnya demi kegiatan tim.","Melaksanakan kegiatan dan menganggap anggota tersebut tidak peduli pada tim bila tidak hadir."],"kunci":2,"bahas":"Menghormati hari besar anggota tersebut, menanyakan kesediaannya, dan mencari jadwal bersama menunjukkan penghargaan terhadap perbedaan keyakinan sekaligus menjaga kebersamaan tim. Melaksanakan kegiatan tanpa pemberitahuan, membatalkan tanpa diskusi, meminta anggota mengabaikan hari besarnya, atau menganggapnya tidak peduli kurang tepat karena tidak menghormati keyakinan anggota atau tidak melibatkan tim dalam keputusan. Langkah-langkah tersebut bukan tanpa pertimbangan praktis, tetapi kurang menjaga penghormatan dan kebersamaan."},{"id":"DKTKP08","subtes":"Tes Karakteristik Pribadi","aspek":"Sosial budaya","soal":"Di lingkungan tempat tinggal Anda, warga dari berbagai latar belakang budaya mengadakan perayaan adat masing-masing. Sikap yang paling tepat adalah ...","opsi":["Menganggap perayaan adat lain mengganggu dan memintanya dihentikan.","Hanya menghadiri perayaan adat dari budaya sendiri dan mengabaikan perayaan lain.","Menilai adat budaya lain lebih rendah daripada adat budaya sendiri.","Meminta seluruh warga mengikuti satu perayaan adat saja.","Menghormati setiap perayaan adat, menjaga kerukunan antarwarga, dan ikut berpartisipasi secara wajar bila diundang."],"kunci":4,"bahas":"Menghormati setiap perayaan adat, menjaga kerukunan, dan berpartisipasi secara wajar bila diundang menunjukkan penghargaan terhadap keberagaman budaya di lingkungan tempat tinggal. Menganggap perayaan lain mengganggu, mengabaikan perayaan lain, merendahkan budaya lain, atau memaksakan satu perayaan kurang tepat karena merusak kerukunan antarwarga. Sikap-sikap tersebut bukan tanpa latar belakang kebiasaan, tetapi kurang mencerminkan penghargaan terhadap perbedaan."},{"id":"DKTKP09","subtes":"Tes Karakteristik Pribadi","aspek":"Teknologi informasi dan komunikasi","soal":"Anda menerima pesan yang mengaku dari pihak layanan dan meminta kata sandi akun kerja Anda melalui tautan yang tidak dikenal. Tindakan yang paling tepat adalah ...","opsi":["Segera mengisi kata sandi melalui tautan tersebut agar akun tidak diblokir.","Meneruskan pesan tersebut kepada seluruh rekan kerja tanpa memeriksa kebenarannya.","Mengabaikan pesan tersebut tanpa memberi tahu siapa pun.","Tidak mengisi kata sandi dan tidak membuka tautan, memeriksa kebenaran pesan melalui jalur yang dapat dipercaya, dan melaporkan pesan tersebut kepada pihak yang menangani keamanan informasi.","Membalas pesan tersebut dengan menanyakan data pribadi pengirimnya."],"kunci":3,"bahas":"Tidak mengisi kata sandi, tidak membuka tautan yang tidak dikenal, memeriksa kebenaran pesan melalui jalur yang dapat dipercaya, dan melaporkan pesan kepada pihak yang menangani keamanan informasi melindungi akun dan membantu mencegah pihak lain menjadi korban. Mengisi kata sandi, meneruskan pesan tanpa pemeriksaan, mengabaikan pesan tanpa pemberitahuan, atau membalas dengan menanyakan data pribadi pengirim kurang tepat karena membahayakan akun atau menyebarkan pesan yang belum jelas kebenarannya. Langkah-langkah tersebut bukan tanpa maksud menyelesaikan masalah, tetapi kurang menjaga keamanan informasi."},{"id":"DKTKP10","subtes":"Tes Karakteristik Pribadi","aspek":"Teknologi informasi dan komunikasi","soal":"Anda selesai menggunakan komputer bersama di kantor dan masih ada dokumen pekerjaan yang terbuka di layar. Tindakan yang paling tepat adalah ...","opsi":["Meninggalkan komputer dalam keadaan menyala dan dokumen tetap terbuka agar mudah dilanjutkan.","Menyimpan dokumen pada tempat yang semestinya, menutup dokumen, dan keluar dari akun sebelum meninggalkan komputer.","Meminta rekan lain menutup dokumen tersebut tanpa memeriksa isinya.","Mematikan layar monitor, tetapi membiarkan dokumen dan akun tetap terbuka.","Menyimpan salinan dokumen di meja komputer agar mudah ditemukan."],"kunci":1,"bahas":"Menyimpan dokumen pada tempat yang semestinya, menutup dokumen, dan keluar dari akun melindungi dokumen pekerjaan dari akses pihak yang tidak berkepentingan. Meninggalkan dokumen terbuka, menyerahkan penutupan tanpa pemeriksaan, hanya mematikan layar, atau menyimpan salinan di meja kurang tepat karena dokumen tetap dapat diakses orang lain. Langkah-langkah tersebut bukan tanpa maksud praktis, tetapi kurang menjaga keamanan dokumen pekerjaan."},{"id":"DKTKP11","subtes":"Tes Karakteristik Pribadi","aspek":"Profesionalisme","soal":"Tugas yang menjadi tanggung jawab Anda terancam terlambat karena kendala yang muncul di tengah pekerjaan. Tindakan yang paling tepat adalah ...","opsi":["Memberi tahu atasan sejak dini tentang kendala yang dihadapi, menjelaskan keadaan dengan jujur, dan mengusulkan rencana penyelesaian.","Menyembunyikan kendala tersebut dan berharap tugas selesai tepat waktu.","Menyalahkan rekan kerja atas kendala yang muncul tanpa memeriksa keadaan sebenarnya.","Menyerahkan tugas dalam keadaan belum selesai tanpa memberi penjelasan.","Meminta rekan lain menyelesaikan seluruh tugas tanpa memberi tahu atasan."],"kunci":0,"bahas":"Memberi tahu atasan sejak dini, menjelaskan keadaan dengan jujur, dan mengusulkan rencana penyelesaian memberi kesempatan untuk mencari jalan keluar bersama dan menjaga kepercayaan atasan. Menyembunyikan kendala, menyalahkan rekan tanpa pemeriksaan, menyerahkan tugas yang belum selesai tanpa penjelasan, atau menyerahkan seluruh tugas tanpa pemberitahuan kurang tepat karena masalah tidak tertangani atau tanggung jawab menjadi tidak jelas. Langkah-langkah tersebut bukan tanpa maksud menghindari masalah, tetapi kurang menunjukkan tanggung jawab profesional."},{"id":"DKTKP12","subtes":"Tes Karakteristik Pribadi","aspek":"Profesionalisme","soal":"Setelah laporan diserahkan, Anda menemukan kesalahan pada bagian laporan yang Anda susun. Tindakan yang paling tepat adalah ...","opsi":["Membiarkan kesalahan tersebut karena laporan sudah diserahkan.","Menyalahkan pihak lain yang ikut memeriksa laporan tersebut.","Mengakui kesalahan, segera memperbaikinya, memberi tahu pihak yang berkepentingan, dan mencatat pelajaran agar kesalahan yang sama tidak terulang.","Memperbaiki kesalahan secara diam-diam tanpa memberi tahu siapa pun.","Menunggu sampai ada pihak lain yang menemukan kesalahan tersebut."],"kunci":2,"bahas":"Mengakui kesalahan, segera memperbaikinya, memberi tahu pihak yang berkepentingan, dan mencatat pelajaran agar kesalahan yang sama tidak terulang menunjukkan tanggung jawab dan menjaga keandalan laporan. Membiarkan kesalahan, menyalahkan pihak lain, memperbaiki secara diam-diam, atau menunggu pihak lain menemukannya kurang tepat karena laporan yang keliru tetap dipakai atau kepercayaan pihak lain berkurang. Langkah-langkah tersebut bukan tanpa maksud menjaga nama baik, tetapi kurang menunjukkan tanggung jawab profesional."},{"id":"DKTKP13","subtes":"Tes Karakteristik Pribadi","aspek":"Anti radikalisme","soal":"Seseorang mengajak Anda bergabung dengan kelompok yang menyebarkan kebencian terhadap kelompok masyarakat lain. Tindakan yang paling tepat adalah ...","opsi":["Bergabung dengan kelompok tersebut agar tidak dikucilkan.","Ikut menyebarkan ajakan kelompok tersebut kepada orang lain.","Diam dan mengikuti kegiatan kelompok tersebut tanpa bertanya.","Menghadapi pengajak dengan kemarahan dan memutus seluruh hubungan tanpa penjelasan.","Menolak ajakan tersebut dengan tenang, tidak ikut menyebarkan kebencian, dan tetap menjaga hubungan baik dengan semua kelompok masyarakat."],"kunci":4,"bahas":"Menolak ajakan dengan tenang, tidak ikut menyebarkan kebencian, dan tetap menjaga hubungan baik dengan semua kelompok menunjukkan keteguhan pada nilai persatuan dan kemanusiaan. Bergabung karena takut dikucilkan, ikut menyebarkan ajakan, mengikuti kegiatan tanpa bertanya, atau menghadapi pengajak dengan kemarahan kurang tepat karena mendukung penyebaran kebencian atau menambah ketegangan. Langkah-langkah tersebut bukan tanpa latar belakang tekanan atau emosi, tetapi kurang menjaga persatuan dan ketenangan."},{"id":"DKTKP14","subtes":"Tes Karakteristik Pribadi","aspek":"Anti radikalisme","soal":"Di media sosial, Anda melihat unggahan yang berisi hasutan terhadap kelompok tertentu dan belum jelas kebenarannya. Tindakan yang paling tepat adalah ...","opsi":["Membagikan unggahan tersebut agar semakin banyak orang mengetahuinya.","Menambahkan komentar yang memperkeruh suasana dalam unggahan tersebut.","Memercayai unggahan tersebut sepenuhnya tanpa memeriksa kebenarannya.","Tidak membagikan unggahan tersebut, memeriksa kebenarannya dari sumber yang dapat dipercaya, dan mengingatkan orang lain dengan tenang agar tidak mudah terhasut.","Mengabaikan unggahan tersebut sepenuhnya, termasuk bila ada orang yang bertanya tentang kebenarannya."],"kunci":3,"bahas":"Tidak membagikan unggahan yang berisi hasutan, memeriksa kebenarannya dari sumber yang dapat dipercaya, dan mengingatkan orang lain dengan tenang membantu mencegah penyebaran hasutan dan menjaga ketenangan bersama. Membagikan unggahan, menambahkan komentar yang memperkeruh suasana, memercayai unggahan tanpa pemeriksaan, atau mengabaikannya sepenuhnya saat ada yang bertanya kurang tepat karena hasutan dapat menyebar atau kebingungan orang lain tidak tertolong. Langkah-langkah tersebut bukan tanpa alasan, tetapi kurang menunjukkan kehati-hatian dalam bermedia sosial."}];
